import java.util.Scanner;

public class Main {

    public void solve() {
        Scanner sc = new Scanner(System.in);
        long W = sc.nextLong();
        long M = sc.nextLong();
        int exponent = 0;
        while (Math.pow(W, exponent) < M) {
            exponent++;
        }
        if (Math.pow(W, exponent) == M) {
            System.out.println("YES");
            return;
        }

        long maxPower = (long) Math.pow(W, exponent);
        long sumSeries = (maxPower - 1) / (W - 1);
        if (maxPower - sumSeries == M) {
            System.out.println("YES");
            return;
        }
        if (checkDivisibility(W, M)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    private boolean checkDivisibility(long W, long M) {
        if (M == 1) {
            return true;
        }
        if (M % W == 0) {
            return checkDivisibility(W, M / W);
        } else if ((M - 1) % W == 0) {
            return checkDivisibility(W, (M - 1) / W);
        } else if ((M + 1) % W == 0) {
            return checkDivisibility(W, (M + 1) / W);
        }
        return false;
    }

    public static void main(String[] args) {
        new Main().solve();
    }
}
